import React, { useState } from "react";
import { useHistory } from "react-router-dom";
import "./adminPortfolio.css";

const AdminPortfolio = () => {
  const history = useHistory();
  const [isHamburgerMenuVisible, setIsHamburgerMenuVisible] = useState(false);
  const [currentView, setCurrentView] = useState('projects'); // Default view

  const handleHamburgerClick = () => {
    setIsHamburgerMenuVisible(!isHamburgerMenuVisible);
  };

  const handleMenuOptionClick = (option) => {
    setIsHamburgerMenuVisible(false);
    setCurrentView(option);
  };

  const handleConfirmClick = () => {
    console.log("Confirm button clicked");
    alert("Confirm action performed.");
  };

  const handleOtpClick = () => {
    console.log("OTP button clicked");
    alert("OTP action performed.");
  };

  const handleEdit = (id) => {
    console.log(`Edit button clicked for item with ID: ${id}`);
  };

  const handleDelete = (id) => {
    console.log(`Delete button clicked for item with ID: ${id}`);
    if (window.confirm("Are you sure you want to delete this item?")) {
      console.log(`Item with ID: ${id} deleted.`);
    }
  };

  const handleView = (id) => {
    console.log(`View button clicked for item with ID: ${id}`);
  };

  return (
    <div>
      {/* Header */}
      <header>
        <button id="back-button" onClick={() => history.goBack()}>Back</button>
        <h1>Admin Portfolio</h1>
        <button id="settings" onClick={handleHamburgerClick}>
          <span className="settings-menu-button">&#9776;</span> {/* Hamburger icon */}
        </button>
        <div className={`hamburger-menu ${isHamburgerMenuVisible ? "visible" : ""}`}>
          <ul>
            <li><a href="#list-of-users" onClick={() => handleMenuOptionClick("users")}>List of Users</a></li>
            <li><a href="#list-of-builders" onClick={() => handleMenuOptionClick("builders")}>List of Builders</a></li>
            <li><a href="#sign-out" onClick={() => handleMenuOptionClick("signOut")}>Sign Out</a></li>
          </ul>
        </div>
      </header>

      {/* Main Content */}
      <main>
        {currentView === 'users' && (
          <div className="table-container">
            {/* Users Table */}
            <section>
              <h2>List of Users</h2>
              <div className="table-wrapper">
                <table>
                  <thead>
                    <tr>
                      <th>User ID</th>
                      <th>Name</th>
                      <th>Project Description</th>
                      <th>Status</th>
                      <th>Action</th>
                    </tr>
                  </thead>
                  <tbody>
                    <tr>
                      <td><a href="user1.html">1</a></td>
                      <td>John Doe</td>
                      <td>Project Alpha</td>
                      <td>Active</td>
                      <td>
                        <div className="action-buttons">
                          <button className="button edit-btn" onClick={() => handleEdit(1)}>Edit</button>
                          <button className="button delete-btn" onClick={() => handleDelete(1)}>Delete</button>
                          <button className="button view-btn" onClick={() => handleView(1)}>View</button>
                        </div>
                      </td>
                    </tr>
                  </tbody>
                </table>
              </div>
            </section>
          </div>
        )}

        {currentView === 'builders' && (
          <div className="table-container">
            {/* Builders Table */}
            <section>
              <h2>List of Builders</h2>
              <div className="table-wrapper">
                <table>
                  <thead>
                    <tr>
                      <th>Builder ID</th>
                      <th>Name</th>
                      <th>Sites</th>
                      <th>Status</th>
                      <th>Action</th>
                    </tr>
                  </thead>
                  <tbody>
                    <tr>
                      <td><a href="builder1.html">1</a></td>
                      <td>Builder Inc.</td>
                      <td>Site A</td>
                      <td>Active</td>
                      <td>
                        <div className="action-buttons">
                          <button className="button edit-btn" onClick={() => handleEdit(1)}>Edit</button>
                          <button className="button delete-btn" onClick={() => handleDelete(1)}>Delete</button>
                          <button className="button view-btn" onClick={() => handleView(1)}>View</button>
                        </div>
                      </td>
                    </tr>
                  </tbody>
                </table>
              </div>
            </section>
          </div>
        )}

        {currentView === 'projects' && (
          <div className="table-container">
            {/* Projects Table */}
            <section>
              <h2>Project Table</h2>
              <div className="table-wrapper">
                <table>
                  <thead>
                    <tr>
                      <th>Project ID</th>
                      <th>User</th>
                      <th>Builder</th>
                      <th>Project Date</th>
                      <th>Status</th>
                    </tr>
                  </thead>
                  <tbody>
                    <tr>
                      <td>1</td>
                      <td>John Doe</td>
                      <td>Builder Inc.</td>
                      <td>2024-08-08</td>
                      <td>Allocated</td>
                    </tr>
                    {/* Add more rows as needed */}
                  </tbody>
                </table>
              </div>
            </section>
          </div>
        )}

        {/* Footer Buttons */}
        <div className="footer-buttons">
          <button className="button confirm-btn" onClick={handleConfirmClick}>Confirm</button>
          <button className="button otp-btn" onClick={handleOtpClick}>OTP</button>
        </div>
      </main>
    </div>
  );
};

export default AdminPortfolio;
